def _H1raw(y):
    return y**2*math.log(y)/(-2*y**2*math.sqrt(1 - y**2) + 2*math.sqrt(1 - y**2)) + (1/4)*math.log(1 - y**2)/math.sqrt(1 - y**2)

def _H2raw(y):
    return 3*y**4*math.log(y)**2/(4*y**4*math.sqrt(1 - y**2) - 8*y**2*math.sqrt(1 - y**2) + 4*math.sqrt(1 - y**2)) - y**2*math.log(y)*math.log(1 - y**2)/(4*y**2*math.sqrt(1 - y**2) - 4*math.sqrt(1 - y**2)) - y**2*math.log(y)**2/(2*y**2*math.sqrt(1 - y**2) - 2*math.sqrt(1 - y**2)) + y**2*math.log(y)/(2*y**2*math.sqrt(1 - y**2) - 2*math.sqrt(1 - y**2)) + (1/16)*math.log(1 - y**2)**2/math.sqrt(1 - y**2) - 1/4*math.log(1 - y**2)/math.sqrt(1 - y**2)

def _H3raw(y):
    return -9*y**6*math.log(y)**3/(8*y**6*math.sqrt(1 - y**2) - 24*y**4*math.sqrt(1 - y**2) + 24*y**2*math.sqrt(1 - y**2) - 8*math.sqrt(1 - y**2)) - 3*y**6*math.log(y)**3/(4*y**6*math.sqrt(1 - y**2) - 12*y**4*math.sqrt(1 - y**2) + 12*y**2*math.sqrt(1 - y**2) - 4*math.sqrt(1 - y**2)) + 9*y**4*math.log(y)**2*math.log(1 - y**2)/(16*y**4*math.sqrt(1 - y**2) - 32*y**2*math.sqrt(1 - y**2) + 16*math.sqrt(1 - y**2)) + 9*y**4*math.log(y)**3/(4*y**4*math.sqrt(1 - y**2) - 8*y**2*math.sqrt(1 - y**2) + 4*math.sqrt(1 - y**2)) - 6*y**4*math.log(y)**2/(4*y**4*math.sqrt(1 - y**2) - 8*y**2*math.sqrt(1 - y**2) + 4*math.sqrt(1 - y**2)) - 3*y**2*math.log(y)*math.log(1 - y**2)**2/(32*y**2*math.sqrt(1 - y**2) - 32*math.sqrt(1 - y**2)) - 3*y**2*math.log(y)**2*math.log(1 - y**2)/(8*y**2*math.sqrt(1 - y**2) - 8*math.sqrt(1 - y**2)) + 3*y**2*math.log(y)**2/(4*y**2*math.sqrt(1 - y**2) - 4*math.sqrt(1 - y**2)) + 3*y**2*math.log(y)*math.log(1 - y**2)/(4*y**2*math.sqrt(1 - y**2) - 4*math.sqrt(1 - y**2)) - 3*y**2*math.log(y)/(4*y**2*math.sqrt(1 - y**2) - 4*math.sqrt(1 - y**2)) - y**2*math.log(y)**3/(2*y**2*math.sqrt(1 - y**2) - 2*math.sqrt(1 - y**2)) + (1/64)*math.log(1 - y**2)**3/math.sqrt(1 - y**2) - 3/16*math.log(1 - y**2)**2/math.sqrt(1 - y**2) + (3/8)*math.log(1 - y**2)/math.sqrt(1 - y**2)
